    if ("'!list.length) return '"'<tr><th scope=\"row\">' + day + '</th><td colspan=\"3\">No rehearsals</td></tr>';
    return list.map((booking) => '<tr><th scope=\"row\">' + day + '</th><td>' + time(booking.start) +
