  const message = groups[candidate.group].name + (editing ? " moved to " : " booked for ") +
    days[candidate.day] + " at " + time(candidate.start) + " in " + rooms[candidate.room].name + ".";
  finish([...rest, candidate], message, candidate.group, candidate.day);
});

