    await field(\"start\").fill(\"20:00\");
    await field(\"save\").click();
    await page.getByRole(\"button\", { name: /"'^Edit Chorus,/ }).click();
    await field("day").selectOption("0");
    await field("start").fill("17:05");
    await field("save").click();
    assert.equal(await field("group-count").innerText(), "4 of 4 booked");
    await page.screenshot({ path: "/private/tmp/callboard-desktop.png" });
  } finally {
    await context.close();
  }

  ({ context, page } = await launch());
  try {
    assert.equal(await page.locator("#group-count").innerText(), "4 of 4 booked");
    assert.equal(await page.getByRole("button", { name: "Edit Chorus, Monday, Main Room, 17:05 to 18:35" }).count(), 1);

    for (const width of [320, 390, 768, 1024, 1440]) {
      await page.setViewportSize({ width, height: 850 });
      assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth), true);
    }
    await page.setViewportSize({ width: 390, height: 850 });
    await page.locator("#day-view").selectOption("2");
    assert.equal(await page.locator('"'.day-column[data-day=\"2\"]').isVisible(), true);
    assert.equal(await page.locator('.day-column[data-day=\"0\"]').isVisible(), false);
    await page.screenshot({ path: \"/private/tmp/callboard-mobile.png\", fullPage: true });
    await page.emulateMedia({ media: \"print\" });
    assert.equal(await page.locator(\"#print-schedule\").isVisible(), true);
    assert.equal(await page.locator(\".workspace\").isVisible(), false);
    for (const format of [\"A4\", \"Letter\"]) {
      await page.pdf({ path: \"/private/tmp/callboard-browser-\" + format + \".pdf\", format });
    }
  } finally {
    await context.close();
  }
  assert.deepEqual(errors, []);
  assert.deepEqual(network, []);
  console.log(\"Passed offline browser interactions, keyboard dialog, profile restart persistence, five viewport widths and browser print.\");
}

run().catch(error => { console.error(error); process.exitCode = 1; });
